import {
  Box,
  Grid,
  FormControl,
  Button,
  Container,
  FormHelperText,
  TextField,
  Typography,
} from "@mui/material";
import React from "react";
import "../../../../styles/animation.css";
import { Controller, useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";

const validationSchema = yup.object().shape({
  full_name: yup.string().trim().required("Full Name is required"),
  company_name: yup.string().trim().required("Company Name is required"),
  email: yup
    .string()
    .trim()
    .email("Invalid email")
    .required("Email is required"),
  phone_number: yup
    .string()
    .trim()
    .matches(/^\+?[0-9]*$/, "Invalid phone number")
    .required("Phone Number is required"),
  message: yup.string().trim().required("Message is required"),
});
const SupportUsForm = React.memo(() => {
  const {
    control,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm({
    defaultValues: {
      full_name: "",
      company_name: "",
      email: "",
      phone_number: "",
      message: "",
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });

  const onSubmit = (data) => {
    let payload = {
      full_name: data.full_name,
      company_name: data.company_name,
      email: data.email,
      phone_number: data.phone_number,
      message: data.message,
    };
    // setLoading(true);

    let apiInstance = null;
    apiInstance = axiosInstance.post(
      ApiEndpoints.GET_SUPPORT_WITH_US.create,
      payload
    );
    apiInstance
      .then((response) => response.data)
      .then((response) => {
        toastSuccess(response.message);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        // setLoading(false);
        reset();
      });
  };
  return (
    <>
      <Box>
        <Container
          maxWidth={"xl"}
          sx={{
            px: { xs: 5, sm: 10, lg: 15, xl: 20 },
          }}
        >
          <Grid container rowGap={{ xs: 8, sm: 10, md: 20 }}>
            <Grid
              item
              xs={12}
              sx={{
                display: "flex",
                flexDirection: "column",
                gap: 3,
                alignItems: "center",
              }}
            >
              <Typography
                sx={{
                  fontSize: {
                    xs: "26px",
                    sm: "44px",
                    md: "54px",
                    lg: "64px",
                  },
                  fontWeight: 500,
                  lineHeight: {
                    xs: "34px",
                    sm: "63px",
                    md: "73px",
                    lg: "83px",
                  },
                  color: "#201D28",
                  textAlign: "center",
                }}
                className="fade-in-up-whoweare"
              >
                Support Us
              </Typography>
              <Typography
                sx={{
                  fontSize: { xs: "14px", lg: "18px" },
                  fontWeight: 500,
                  lineHeight: { xs: "26px", lg: "28px" },
                  color: "#69668E",
                  textAlign: "center",
                }}
                className="fade-in-up-whoweare"
              >
                Our main office in Sultanate Of Oman, Muscat
              </Typography>
            </Grid>
            <Grid
              container
              item
              // rowGap={{ md: 8 }}
              // xs={12}
              sx={{
                border: "1.5px solid #E2E5EA",
                borderRadius: "15px",
                py: { xs: 5, md: 10 },
                px: { xs: 5, md: 15 },
                // mt: 15,
              }}
            >
              <Grid item xs={12} pb={8}>
                <Typography
                  sx={{
                    fontSize: {
                      xs: "26px",
                      md: "30px",
                      lg: "40px",
                    },
                    lineHeight: { xs: "34px", md: "44px", lg: "50px" },
                    fontWeight: { xs: 500, md: 700 },
                    color: { xs: "#201D28", md: "#602DE1" },
                  }}
                >
                  Get Support with Us
                </Typography>
              </Grid>
              <Grid item xs={12}>
                <form onSubmit={handleSubmit(onSubmit)}>
                  <Grid container rowSpacing={{ xs: 4, sm: 7 }}>
                    <Grid
                      item
                      container
                      xs={12}
                      rowSpacing={{ xs: 5, md: 0 }}
                      columnSpacing={{ xs: 3, md: 5 }}
                    >
                      <Grid item xs={6}>
                        <FormControl fullWidth>
                          <Controller
                            name="full_name"
                            control={control}
                            render={({ field }) => (
                              <TextField
                                error={Boolean(errors.full_name)}
                                {...field}
                                placeholder="Full Name *"
                                fullWidth
                                sx={{
                                  "& fieldset": { border: "none" },
                                  "&::placeholder": {
                                    color: "#989898",
                                    fontWeight: 500,
                                  },
                                }}
                                inputProps={{
                                  style: {
                                    border: "1.5px solid #C8C8C8",
                                    borderRadius: "14px",
                                  },
                                }}
                              />
                            )}
                          />
                          {errors.full_name && (
                            <FormHelperText sx={{ color: "#ff0000" }}>
                              {errors.full_name.message}
                            </FormHelperText>
                          )}
                        </FormControl>
                      </Grid>
                      <Grid item xs={6}>
                        <FormControl fullWidth>
                          <Controller
                            name="company_name"
                            control={control}
                            render={({ field }) => (
                              <TextField
                                error={Boolean(errors.company_name)}
                                {...field}
                                placeholder="Company Name *"
                                fullWidth
                                sx={{
                                  "& fieldset": { border: "none" },
                                  "&::placeholder": {
                                    color: "#989898",
                                    fontWeight: 500,
                                  },
                                }}
                                inputProps={{
                                  style: {
                                    border: "1.5px solid #C8C8C8",
                                    borderRadius: "14px",
                                  },
                                }}
                              />
                            )}
                          />
                          {errors.company_name && (
                            <FormHelperText sx={{ color: "#ff0000" }}>
                              {errors.company_name.message}
                            </FormHelperText>
                          )}
                        </FormControl>
                      </Grid>
                    </Grid>
                    <Grid
                      item
                      container
                      xs={12}
                      rowSpacing={{ xs: 5, md: 0 }}
                      columnSpacing={{ xs: 3, md: 5 }}
                    >
                      <Grid item xs={6}>
                        <FormControl fullWidth>
                          <Controller
                            name="email"
                            control={control}
                            render={({ field }) => (
                              <TextField
                                error={Boolean(errors.email)}
                                {...field}
                                placeholder="Email *"
                                fullWidth
                                sx={{
                                  "& fieldset": { border: "none" },
                                  "&::placeholder": {
                                    color: "#989898",
                                    fontWeight: 500,
                                  },
                                }}
                                inputProps={{
                                  style: {
                                    border: "1.5px solid #C8C8C8",
                                    borderRadius: "14px",
                                  },
                                }}
                              />
                            )}
                          />
                          {errors.email && (
                            <FormHelperText sx={{ color: "#ff0000" }}>
                              {errors.email.message}
                            </FormHelperText>
                          )}
                        </FormControl>
                      </Grid>
                      <Grid item xs={6}>
                        <FormControl fullWidth>
                          <Controller
                            name="phone_number"
                            control={control}
                            render={({ field }) => (
                              <TextField
                                error={Boolean(errors.phone_number)}
                                {...field}
                                placeholder="Phone Number *"
                                fullWidth
                                sx={{
                                  "& fieldset": { border: "none" },
                                  "&::placeholder": {
                                    color: "#989898",
                                    fontWeight: 500,
                                  },
                                }}
                                inputProps={{
                                  style: {
                                    border: "1.5px solid #C8C8C8",
                                    borderRadius: "14px",
                                  },
                                }}
                              />
                            )}
                          />
                          {errors.phone_number && (
                            <FormHelperText sx={{ color: "#ff0000" }}>
                              {errors.phone_number.message}
                            </FormHelperText>
                          )}
                        </FormControl>
                      </Grid>
                    </Grid>
                    <Grid item xs={12}>
                      <FormControl fullWidth>
                        <Controller
                          name="message"
                          control={control}
                          render={({ field }) => (
                            <TextField
                              error={Boolean(errors.message)}
                              {...field}
                              placeholder="Your Message Here..."
                              multiline
                              rows={3.5}
                              fullWidth
                              sx={{
                                "& fieldset": { border: "none" },
                                "& .MuiOutlinedInput-root": {
                                  padding: 0, // Remove padding from the root
                                  "& .MuiOutlinedInput-input": {
                                    padding: "8.5px 14px", // Add custom padding if needed
                                  },
                                },
                                "&::placeholder": {
                                  color: "#989898",
                                  fontWeight: 500,
                                },
                              }}
                              inputProps={{
                                style: {
                                  border: "1.5px solid #C8C8C8",
                                  borderRadius: "14px",
                                },
                              }}
                            />
                          )}
                        />
                        {errors.message && (
                          <FormHelperText sx={{ color: "#ff0000" }}>
                            {errors.message.message}
                          </FormHelperText>
                        )}
                      </FormControl>
                    </Grid>
                    <Grid item xs={12}>
                      <Box>
                        <Button
                          type="submit"
                          variant="contained"
                          sx={{
                            fontSize: { xs: "14px", md: "16px" },
                            fontWeight: 600,
                            borderRadius: "16px",
                            padding: "3px 24px",
                          }}
                        >
                          SUBMIT
                        </Button>
                      </Box>
                    </Grid>
                  </Grid>
                </form>
              </Grid>
            </Grid>
          </Grid>
        </Container>
      </Box>
    </>
  );
});

export default SupportUsForm;
